import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as a,c as i,f as r,q as n,D as o,Q as s,g as u}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const d="/assets/command-cover.COfYwB_g.jpg",g="/assets/introduction.CYhY9Oed.png",x="/assets/introduction-1.rE1zCIpW.png",q=JSON.parse('{"title":"Linux 简介与常见发行版","description":"","frontmatter":{},"headers":[],"relativePath":"column/Linux/基础入门/Linux 简介与常见发行版.md","filePath":"column/Linux/基础入门/Linux 简介与常见发行版.md","lastUpdated":1787885834000}'),h={name:"column/Linux/基础入门/Linux 简介与常见发行版.md"};function c(_,t,f,L,b,p){const l=a("ArticleMetadata");return r(),i("div",null,[t[0]||(t[0]=n("h1",{id:"linux-简介与常见发行版",tabindex:"-1"},[u("Linux 简介与常见发行版 "),n("a",{class:"header-anchor",href:"#linux-简介与常见发行版","aria-label":'Permalink to "Linux 简介与常见发行版"'},"​")],-1)),o(l),t[1]||(t[1]=s('<nav class="table-of-contents"><ul><li><a href="#_1-什么是-linux">1. 什么是 Linux？</a><ul><li><a href="#linux-内核-vs-操作系统">Linux 内核 vs 操作系统</a></li></ul></li><li><a href="#_2-为什么-linux-如此重要">2. 为什么 Linux 如此重要？</a></li><li><a href="#_3-常见-linux-发行版及家族分类">3. 常见 Linux 发行版及家族分类</a><ul><li><a href="#_3-1-debian-ubuntu-派系-易用性与社区之王">3.1 Debian / Ubuntu 派系（易用性与社区之王）</a></li><li><a href="#_3-2-red-hat-rhel-派系-企业级标准">3.2 Red Hat (RHEL) 派系（企业级标准）</a></li><li><a href="#_3-3-arch-linux-派系-极客与定制玩家">3.3 Arch Linux 派系（极客与定制玩家）</a></li><li><a href="#_3-4-suse-派系-欧洲企业之王">3.4 SUSE 派系（欧洲企业之王）</a></li></ul></li><li><a href="#_4-主流发行版横向对比与选型建议">4. 主流发行版横向对比与选型建议</a><ul><li><a href="#快速选择建议">快速选择建议</a></li></ul></li><li><a href="#_5-总结">5. 总结</a></li></ul></nav><p><img src="'+d+'" alt="" loading="lazy"></p><p>在开始学习 Linux 命令、权限、系统服务之前，我们需要先搞清楚一件事：<strong>Linux 到底是什么？</strong> 以及市面上那么多叫「Linux」的系统，它们之间到底有什么区别。</p><h2 id="_1-什么是-linux" tabindex="-1">1. 什么是 Linux？ <a class="header-anchor" href="#_1-什么是-linux" aria-label="Permalink to &quot;1. 什么是 Linux？&quot;">​</a></h2><p>很多人常说「我在用 Linux」，但更准确的说法是：<strong>我在用一个基于 Linux 内核的操作系统</strong>。</p><p><img src="'+g+'" alt="" loading="lazy"></p><h3 id="linux-内核-vs-操作系统" tabindex="-1">Linux 内核 vs 操作系统 <a class="header-anchor" href="#linux-内核-vs-操作系统" aria-label="Permalink to &quot;Linux 内核 vs 操作系统&quot;">​</a></h3><ul><li><strong>Linux 内核（Kernel）</strong>：由林纳斯·托瓦兹（Linus Torvalds）于 1991 年发起并开源。它是系统的底层核心，专门负责管理硬件资源（CPU、内存、磁盘、网络等）与进程调度。</li><li><strong>操作系统（GNU/Linux）</strong>：只有内核是无法直接作为完整系统给用户使用的。将 Linux 内核与 GNU 项目的命令行工具（Shell、核心工具链）、包管理器及桌面环境打包在一起，才构成了可用的系统。</li></ul><blockquote><p><strong>核心公式</strong>：Linux 发行版 (Distribution) = Linux 内核 + GNU 系统工具 + 包管理器 + 预装应用/桌面环境</p></blockquote><h2 id="_2-为什么-linux-如此重要" tabindex="-1">2. 为什么 Linux 如此重要？ <a class="header-anchor" href="#_2-为什么-linux-如此重要" aria-label="Permalink to &quot;2. 为什么 Linux 如此重要？&quot;">​</a></h2><ol><li><strong>服务器领域的绝对霸主</strong>：全球绝大多数网站、云计算服务、后端 API 以及高性能数据库均部署在 Linux 上。</li><li><strong>开源且免费</strong>：无商业授权费用，代码透明，支持全球开发者共同维护与定制。</li><li><strong>稳定与高安全性</strong>：基于严格的 Unix 权限管理模型，系统服务可以连续稳定运行数年而无需重启。</li><li><strong>高扩展与高定制性</strong>：从 TOP500 超级计算机，到智能手机（Android）、路由器及物联网设备，均可按需裁剪。</li></ol><h2 id="_3-常见-linux-发行版及家族分类" tabindex="-1">3. 常见 Linux 发行版及家族分类 <a class="header-anchor" href="#_3-常见-linux-发行版及家族分类" aria-label="Permalink to &quot;3. 常见 Linux 发行版及家族分类&quot;">​</a></h2><p>虽然市面上发行版有数百种，但它们绝大多数继承自几大核心系谱：</p><p><img src="'+x+'" alt="" loading="lazy"></p><p>发行版可以简单理解为：「内核 + 各种软件 + 独特的包管理方式 + 厂商/社区的特色工具」。市面上的主流发行版主要分为以下几个家族系谱：</p><h3 id="_3-1-debian-ubuntu-派系-易用性与社区之王" tabindex="-1">3.1 Debian / Ubuntu 派系（易用性与社区之王） <a class="header-anchor" href="#_3-1-debian-ubuntu-派系-易用性与社区之王" aria-label="Permalink to &quot;3.1 Debian / Ubuntu 派系（易用性与社区之王）&quot;">​</a></h3><ul><li><strong>Debian</strong>：Linux 界的大老级开源项目，以<strong>极致的稳定性</strong>和<strong>坚守自由软件精神</strong>著称。软件更新偏保守，常用于追求绝对稳定的服务器。</li><li><strong>Ubuntu</strong>：基于 Debian 二次开发，目前全球最流行、对新手最友好的发行版之一。 <ul><li><strong>特点</strong>：开箱即用，硬件兼容性好，社区生态极度丰富。</li><li><strong>主流版本</strong>：推荐使用 <strong>Ubuntu Server LTS</strong>（长期支持版）。</li></ul></li><li><strong>Linux Mint / Deepin（深度）</strong>：基于 Debian/Ubuntu，界面美观贴心，适合作为桌面系统使用。</li></ul><h3 id="_3-2-red-hat-rhel-派系-企业级标准" tabindex="-1">3.2 Red Hat (RHEL) 派系（企业级标准） <a class="header-anchor" href="#_3-2-red-hat-rhel-派系-企业级标准" aria-label="Permalink to &quot;3.2 Red Hat (RHEL) 派系（企业级标准）&quot;">​</a></h3><ul><li><strong>RHEL (Red Hat Enterprise Linux)</strong>：红帽公司推出的企业级系统，提供商业技术支持，是金融和世界 500 强企业的首选。</li><li><strong>Rocky Linux / AlmaLinux</strong>：在 CentOS 改变策略后，社区发起的 <strong>100% 兼容 RHEL</strong> 的开源替代方案，目前是企业生产环境的热门选择。</li><li><strong>Fedora</strong>：红帽公司的“新技术试验田”，更新频繁，适合喜欢体验最新内核与软件特性的开发者。</li></ul><h3 id="_3-3-arch-linux-派系-极客与定制玩家" tabindex="-1">3.3 Arch Linux 派系（极客与定制玩家） <a class="header-anchor" href="#_3-3-arch-linux-派系-极客与定制玩家" aria-label="Permalink to &quot;3.3 Arch Linux 派系（极客与定制玩家）&quot;">​</a></h3><ul><li><strong>Arch Linux</strong>：采用 <strong>滚动更新（Rolling Release）</strong> 机制，遵从极简理念。系统只提供基础框架，从安装到组件选择完全由用户手动配置。</li><li><strong>Manjaro</strong>：基于 Arch 打造，预装了图形化安装程序与桌面，降低了 Arch 的上手门槛。</li></ul><h3 id="_3-4-suse-派系-欧洲企业之王" tabindex="-1">3.4 SUSE 派系（欧洲企业之王） <a class="header-anchor" href="#_3-4-suse-派系-欧洲企业之王" aria-label="Permalink to &quot;3.4 SUSE 派系（欧洲企业之王）&quot;">​</a></h3><ul><li><strong>openSUSE</strong>：源自德国的知名发行版，以强大的图形化系统配置工具 <strong>YaST</strong> 闻名，在欧洲及工业自动化领域应用广泛。</li></ul><h2 id="_4-主流发行版横向对比与选型建议" tabindex="-1">4. 主流发行版横向对比与选型建议 <a class="header-anchor" href="#_4-主流发行版横向对比与选型建议" aria-label="Permalink to &quot;4. 主流发行版横向对比与选型建议&quot;">​</a></h2><p>针对不同场景和需求，以下是常见发行版的特点汇总与选型对照：</p><table tabindex="0"><thead><tr><th style="text-align:left;">派系 / 发行版</th><th style="text-align:left;">包管理器</th><th style="text-align:left;">核心优势</th><th style="text-align:left;">推荐应用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ubuntu</strong></td><td style="text-align:left;"><code>apt</code> (dpkg)</td><td style="text-align:left;">社区庞大，文档丰富，软件生态最好</td><td style="text-align:left;">新手入门、开发环境、AI/算法研究</td></tr><tr><td style="text-align:left;"><strong>Debian</strong></td><td style="text-align:left;"><code>apt</code> (dpkg)</td><td style="text-align:left;">系统轻量，资源占用低，极致稳定</td><td style="text-align:left;">追求稳定的底层服务器、VPS 部署</td></tr><tr><td style="text-align:left;"><strong>Rocky / Alma</strong></td><td style="text-align:left;"><code>dnf</code> / <code>yum</code></td><td style="text-align:left;">100% 兼容 RHEL，企业级稳定</td><td style="text-align:left;">企业生产环境、运维、后端服务</td></tr><tr><td style="text-align:left;"><strong>Fedora</strong></td><td style="text-align:left;"><code>dnf</code></td><td style="text-align:left;">引入最新技术与最新内核，更新积极</td><td style="text-align:left;">前沿技术尝鲜、桌面个人开发</td></tr><tr><td style="text-align:left;"><strong>Arch Linux</strong></td><td style="text-align:left;"><code>pacman</code></td><td style="text-align:left;">软件库 (AUR) 庞大，高度自由定制</td><td style="text-align:left;">极客玩家、深入学习 Linux 系统底层</td></tr></tbody></table><h3 id="快速选择建议" tabindex="-1">快速选择建议 <a class="header-anchor" href="#快速选择建议" aria-label="Permalink to &quot;快速选择建议&quot;">​</a></h3><ul><li><strong>完全新手 / 个人开发</strong> ➡️ 首选 <strong>Ubuntu</strong></li><li><strong>后端开发 / 运维 / 生产服务器</strong> ➡️ 推荐 <strong>Ubuntu Server</strong> 或 <strong>Rocky Linux</strong></li><li><strong>想深入研究系统原理</strong> ➡️ 尝试手动折腾 <strong>Arch Linux</strong></li></ul><h2 id="_5-总结" tabindex="-1">5. 总结 <a class="header-anchor" href="#_5-总结" aria-label="Permalink to &quot;5. 总结&quot;">​</a></h2><ul><li><strong>Linux 本身是内核</strong>，我们平时使用的是打包好的各类「发行版」。</li><li>不同发行版的本质区别主要在于：<strong>包管理工具</strong>、<strong>软件更新策略（滚动更新 vs 定期 LTS）</strong> 以及<strong>系统预装组件</strong>。</li><li>对于初学者来说，<strong>不必在“选哪个发行版更酷”上消耗精力</strong>。选定 Ubuntu 或 Rocky Linux 后，尽快把基础命令行、文件权限、网络及服务管理打牢才是最重要的。</li></ul>',30))])}const k=e(h,[["render",c]]);export{q as __pageData,k as default};
